def config_value(text: str, key: str) -> str:
    """Return the value for ``key`` in ``name=value`` config text.

    ``text`` is parsed line by line. Each line holds one ``name=value``
    pair, split on the first ``=``. Surrounding whitespace is stripped from
    both name and value. Blank lines and lines whose first non-space
    character is ``#`` are ignored. If ``key`` does not appear, return an
    empty string. This function never reads files; it works only on
    ``text``.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_returns_value_for_existing_key() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_returns_empty_string_for_missing_key() -> None:
    assert config_value("host=localhost", "port") == ""


def test_returns_empty_string_for_empty_text() -> None:
    assert config_value("", "host") == ""


def test_value_may_contain_equals_sign() -> None:
    assert config_value("expr=a=b", "expr") == "a=b"


def test_strips_whitespace_around_key_and_value() -> None:
    assert config_value("  name  =  alice  ", "name") == "alice"


def test_ignores_comment_lines() -> None:
    assert config_value("# port=1\nport=2", "port") == "2"


def test_ignores_blank_lines() -> None:
    assert config_value("\n\nkey=val\n\n", "key") == "val"
